function pathPoly(points,fill,stroke=null,width=1){ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1]));ctx.closePath();if(fill){ctx.fillStyle=fill;ctx.fill()}if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=width;ctx.stroke()}}
function drawTree(x,y,s){ctx.save();ctx.translate(x,y);ctx.fillStyle='#15382d';ctx.fillRect(-3*s,0,6*s,16*s);for(let i=0;i<3;i++){ctx.beginPath();ctx.moveTo(0,-37*s+i*16*s);ctx.lineTo(-18*s+i*4*s,-5*s+i*16*s);ctx.lineTo(18*s-i*4*s,-5*s+i*16*s);ctx.closePath();ctx.fillStyle=i===1?'#24533a':'#1b4533';ctx.fill();ctx.strokeStyle='#e7f4df77';ctx.lineWidth=2*s;ctx.beginPath();ctx.moveTo(-12*s+i*2*s,-8*s+i*16*s);ctx.lineTo(0,-31*s+i*16*s);ctx.lineTo(12*s-i*2*s,-8*s+i*16*s);ctx.stroke()}ctx.restore()}
function drawScene(){ctx.setTransform(scale,0,0,scale,0,0);ctx.clearRect(0,0,W,H);const bg=ctx.createLinearGradient(0,0,0,H);bg.addColorStop(0,'#1c4538');bg.addColorStop(.58,'#12352d');bg.addColorStop(1,'#0c2825');ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);
// Snowy midnight fir line
for(let i=0;i<11;i++){const x=i*102-17,y=H*(.085+(i%3)*.035);drawTree(x,y,1.05+(i%4)*.12);if(i%2===0){ctx.fillStyle='#ffd178';ctx.beginPath();ctx.arc(x+19,y-27,2.4,0,7);ctx.fill()}}
for(let i=0;i<42;i++){const x=(i*173+31)%1000,y=(i*241+17)%(H*.63);ctx.fillStyle=`rgba(255,255,255,${.18+(i%5)*.09})`;ctx.beginPath();ctx.arc(x,y,1+(i%3)*.45,0,7);ctx.fill()}
const top=H*.12,bot=H*.94;
// Rink shadow and raised timber sides
pathPoly([[205,top],[795,top],[920,bot],[80,bot]],'#081c19aa');pathPoly([[214,top],[786,top],[910,bot],[90,bot]],'#8b6037','#d6ae6e',3);
pathPoly([[224,top+7],[776,top+7],[896,bot-7],[104,bot-7]],'#d5e7db','#f5e3bf',2);
const ice=ctx.createLinearGradient(0,top,0,bot);ice.addColorStop(0,'#d7f0e5');ice.addColorStop(.45,'#b8ded3');ice.addColorStop(1,'#8dc2b8');pathPoly([[232,top+14],[768,top+14],[883,bot-16],[117,bot-16]],ice);
// Ice grains
ctx.save();pathPoly([[232,top+14],[768,top+14],[883,bot-16],[117,bot-16]],'rgba(255,255,255,.02)');ctx.clip();for(let i=0;i<100;i++){const x=(i*173+47)%1000,y=top+(i*113%(bot-top));ctx.fillStyle=`rgba(255,255,255,${.1+(i%4)*.04})`;ctx.fillRect(x,y,1.5,1.5)}ctx.restore();
const stripeY=H*.49;ctx.beginPath();ctx.moveTo(179,stripeY);ctx.lineTo(821,stripeY);ctx.strokeStyle='#fff9';ctx.lineWidth=3;ctx.stroke();ctx.beginPath();ctx.ellipse(500,stripeY+H*.08,108,32,0,0,Math.PI*2);ctx.strokeStyle='#3d9b8c88';ctx.lineWidth=3;ctx.stroke();ctx.beginPath();ctx.ellipse(500,stripeY+H*.08,68,19,0,0,Math.PI*2);ctx.strokeStyle='#ed6a5888';ctx.lineWidth=3;ctx.stroke();
// Deck labels
ctx.save();ctx.translate(500,H*.73);ctx.fillStyle='#317a6c38';ctx.font='900 29px Trebuchet MS';ctx.textAlign='center';ctx.letterSpacing='8px';ctx.fillText('NORTH POLE',0,0);ctx.restore();
// Target house rings
ctx.beginPath();ctx.ellipse(500,H*.31,122,40,0,0,Math.PI*2);ctx.fillStyle='#f7fffa55';ctx.fill();ctx.strokeStyle='#df716799';ctx.lineWidth=4;ctx.stroke();ctx.beginPath();ctx.ellipse(500,H*.31,72,23,0,0,Math.PI*2);ctx.strokeStyle='#2e8e7c99';ctx.lineWidth=3;ctx.stroke();
// Guard rails with gold gleam
ctx.beginPath();ctx.moveTo(225,top+15);ctx.lineTo(120,bot-17);ctx.moveTo(775,top+15);ctx.lineTo(880,bot-17);ctx.strokeStyle='#96633e';ctx.lineWidth=11;ctx.stroke();ctx.strokeStyle='#ffe2a488';ctx.lineWidth=2;ctx.stroke();
// Rope lights
for(let i=0;i<15;i++){const t=i/14,x=225+(120-225)*t,y=top+15+(bot-top-32)*t;ctx.fillStyle=i%3===0?'#ffcd70':'#f0f8e9';ctx.shadowColor=ctx.fillStyle;ctx.shadowBlur=6;ctx.beginPath();ctx.arc(x+6,y,3,0,7);ctx.fill();ctx.beginPath();ctx.arc(775+(880-775)*t,y,3,0,7);ctx.fill()}ctx.shadowBlur=0;
// Puck starting spot and aim guide
if(!animating&&!gameOver&&shots<2){const py=H*.87;ctx.beginPath();ctx.ellipse(500,py,32,11,0,0,7);ctx.fillStyle='#fff8';ctx.fill();const len=aim?Math.min(160,55+aim.power*8):100,ax=aim?aim.x:0,ay=aim?aim.y:-1;ctx.beginPath();ctx.moveTo(500,py);ctx.lineTo(500+ax*len,py+ay*len);ctx.strokeStyle=drag?'#e85e4e':'#fdf7d1aa';ctx.lineWidth=drag?3:2;ctx.setLineDash([6,8]);ctx.stroke();ctx.setLineDash([]);if(drag){ctx.fillStyle='#173c32';ctx.font='900 13px Trebuchet MS';ctx.textAlign='center';ctx.fillText(`POWER ${Math.round(aim.power*7)}%`,500,py+38)}}
// Elves and puck draw ordering
elves.slice().sort((a,b)=>a.y-b.y).forEach(drawElf);if(puck?.active)drawPuck(puck.x,puck.y,puck.r);
// Wind arrow
ctx.save();ctx.translate(500,H*.54);ctx.strokeStyle='#fff8';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(0,0);ctx.lineTo(wind*24,-12);ctx.lineTo(wind*17,-12);ctx.moveTo(wind*24,-12);ctx.lineTo(wind*20,-5);ctx.stroke();ctx.restore();
}

